  PRIMARY KEY ("id"),
  CONSTRAINT "problems_difficulties_problems" FOREIGN KEY ("difficulty_id") REFERENCES "public"."difficulties" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "problems_users_problems" FOREIGN KEY ("author_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
