  "total_count" bigint NOT NULL DEFAULT 0,
  "time_ms" bigint NULL,
  "memory_kb" bigint NULL,
  "error_message" text NULL,
  "problem_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "submissions_problems_submissions" FOREIGN KEY ("problem_id") REFERENCES "public"."problems" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "submissions_users_submissions" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
